import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";var i=JSON.parse(`{"title":"Configuration","description":"","frontmatter":{},"headers":[],"relativePath":"guide/configuration.md","filePath":"guide/configuration.md","lastUpdated":1786978836000}`),a={name:`guide/configuration.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to “Configuration”">​</a></h1><p>Everything is configured through environment variables. There is no config file and no command-line flag.</p><table tabindex="0"><thead><tr><th>Variable</th><th>Required</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>AUDIOBOOKSHELF_URL</code></td><td>yes</td><td>—</td><td>Base URL of the instance, e.g. <code>https://abs.example.com</code></td></tr><tr><td><code>AUDIOBOOKSHELF_API_KEY</code></td><td>yes</td><td>—</td><td>API key, sent as <code>Authorization: Bearer …</code></td></tr><tr><td><code>AUDIOBOOKSHELF_READ_ONLY</code></td><td>no</td><td><code>false</code></td><td><code>true</code> registers only the 29 read tools</td></tr><tr><td><code>AUDIOBOOKSHELF_INSECURE_TLS</code></td><td>no</td><td><code>false</code></td><td><code>true</code> accepts self-signed certificates for this connection</td></tr></tbody></table><p>Only the exact string <code>true</code> enables the two booleans. <code>1</code>, <code>yes</code> and <code>TRUE</code> do not — which is worth knowing, because a typo in <code>AUDIOBOOKSHELF_READ_ONLY</code> fails <em>open</em>, with the write tools registered. The server logs which switches are active at startup; check that line rather than trusting the spelling.</p><p>See the <a href="/reference/environment">environment reference</a> for the same table with the validation rules.</p><h2 id="audiobookshelf-url" tabindex="-1"><code>AUDIOBOOKSHELF_URL</code> <a class="header-anchor" href="#audiobookshelf-url" aria-label="Permalink to “AUDIOBOOKSHELF_URL”">​</a></h2><p>Validated at startup with <code>new URL()</code>. The server <strong>exits</strong> if it is:</p><ul><li>unparseable,</li><li>not <code>http://</code> or <code>https://</code>,</li><li>or carries credentials in the form <code>https://user:pass@host</code> — those would end up in logs and error messages, and the API key is the supported mechanism.</li></ul><p>Trailing slashes are stripped, so <code>https://abs.example.com/</code> and <code>https://abs.example.com</code> behave identically.</p><p>Plain <code>http://</code> to a <strong>non-loopback</strong> host produces a warning and keeps going: the API key would cross the network unencrypted. <code>http://localhost</code> and <code>http://127.*</code> do not warn.</p><div class="tip custom-block"><p class="custom-block-title">Reverse proxies and subpaths</p><p>Point the URL at whatever serves the Audiobookshelf UI. If it lives under a subpath, include it — <code>https://media.example.com/audiobookshelf</code>. The server appends <code>/api/…</code> to exactly what you give it.</p></div><h2 id="audiobookshelf-api-key" tabindex="-1"><code>AUDIOBOOKSHELF_API_KEY</code> <a class="header-anchor" href="#audiobookshelf-api-key" aria-label="Permalink to “AUDIOBOOKSHELF_API_KEY”">​</a></h2><p>Created under <strong>Settings → Users → API Keys</strong> by an admin, shown once.</p><p>The key is <strong>deleted from <code>process.env</code> once the configuration has been read</strong>, so it is not visible to child processes or in <code>/proc/&lt;pid&gt;/environ</code> for the lifetime of the process.</p><p>Credentials are only required when a tool actually calls the API — not at startup. The server starts, handshakes and lists its tools without them, and every call then fails with the setup instructions. That is what lets a registry sandbox enumerate the tools.</p><h2 id="audiobookshelf-read-only" tabindex="-1"><code>AUDIOBOOKSHELF_READ_ONLY</code> <a class="header-anchor" href="#audiobookshelf-read-only" aria-label="Permalink to “AUDIOBOOKSHELF_READ_ONLY”">​</a></h2><p><code>true</code> means the 15 write tools are <strong>never registered</strong> — not registered and then refused. A client asking for <code>tools/list</code> sees 29 tools, and there is no capability advertised that the server would decline to provide.</p><p>Use it when you want the library answerable but not editable, which is most of the time.</p><h2 id="audiobookshelf-insecure-tls" tabindex="-1"><code>AUDIOBOOKSHELF_INSECURE_TLS</code> <a class="header-anchor" href="#audiobookshelf-insecure-tls" aria-label="Permalink to “AUDIOBOOKSHELF_INSECURE_TLS”">​</a></h2><p>For an instance behind a self-signed or internal-CA certificate.</p><p>This does <strong>not</strong> set <code>NODE_TLS_REJECT_UNAUTHORIZED</code>. It creates a scoped <a href="https://undici.nodejs.org/" target="_blank" rel="noreferrer">undici</a> dispatcher used only for requests to your Audiobookshelf, so nothing else the process does is affected. The server prints a warning to stderr while it is on.</p><p>Prefer adding your CA to the system trust store; this switch is the escape hatch, not the recommendation.</p><h2 id="fixed-behaviour" tabindex="-1">Fixed behaviour <a class="header-anchor" href="#fixed-behaviour" aria-label="Permalink to “Fixed behaviour”">​</a></h2><p>Not configurable, deliberately:</p><table tabindex="0"><thead><tr><th>Behaviour</th><th>Value</th><th>Why</th></tr></thead><tbody><tr><td>Request timeout</td><td>15 s</td><td>A hung request would hang the tool call</td></tr><tr><td>Redirects</td><td>never followed</td><td>A redirect would replay the <code>Authorization</code> header at another host</td></tr><tr><td>List cap</td><td>100 entries</td><td>One call must not be able to flood the context</td></tr><tr><td>Description cap</td><td>800 characters</td><td>Metadata-provider descriptions run to many kB</td></tr><tr><td>Error body cap</td><td>2000 chars</td><td>HTML error pages are dropped entirely, other bodies truncated</td></tr><tr><td>Confirm-token TTL</td><td>5 minutes</td><td>Long enough for a round trip, short enough not to linger</td></tr></tbody></table>`,25)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};